<!-- 
  // DOESN'T WORK YET — MUST CHECK AGAIN TO BE SURE
  @component 
  Creates list items with custom SVGs

  - @prop {string} `class` - Classes to add to the component.
  - @prop {array|object} `items` - **Required** Items in the list.
    - `content` - Content for the list item. This will be parsed as Markdown automatically. Required
    - `icon` - Name of the SVG to use for this specific item. 
    - `emoji` - Emoji to use for the specific item. 
-->

<script>
  import Icon from '../Icon/Icon.svelte'
  import Markdown from '../Markdown/Markdown.svelte'

  let {
    class: klass = '',
    sublistClass = '',
    icon = '',
    iconClass,
    emoji,
    emojiClass,
    items: rawItems = [],
    ...rest
  } = $props()

  const items = $derived(rawItems.map(item => createItemStructure(item)))

  function createItemStructure(item) {
    if (typeof item === 'string')
      return {
        icon,
        iconClass,
        emoji,
        emojiClass,
        content: item,
      }

    if (item.items?.length > 0) {
      return {
        ...createItemStructure(item.value),
        items: item.items.map(i => createItemStructure(i)),
      }
    }

    return item
  }
</script>

{#snippet ul(items, isSublist)}
  <ul {...rest} class={`fancylist ${klass} ${isSublist ? sublistClass : ''}`}>
    {#each items as item (item)}
      <li>
        {#if item.icon}
          <Icon class={item.iconClass} aria-hidden {icon} />
        {/if}
        {#if item.emoji}
          <span class="emoji {item.emojiClass}">{item.emoji}</span>
        {/if}
        <span><Markdown content={item.content} inline /></span>
        {#if item.items}
          {@render ul(item.items, isSublist)}
        {/if}
      </li>
    {/each}
  </ul>
{/snippet}

<!-- Need role because we use hide the bullets and replace them with SVGs. -->
{@render ul(items)}
